import type { ComponentProps } from "react";

import { useAGUILoadingStackedContext } from "./agui-loading-stacked";

export type AGUILoadingStackedEarlierProps = Omit<ComponentProps<"span">, "children">;

// -----
// "+2 earlier": how many rows maxVisible hides.
// Shows nothing when all rows fit.
// -----
export function AGUILoadingStackedEarlier(props: AGUILoadingStackedEarlierProps) {
  const { state, view, maxVisible } = useAGUILoadingStackedContext(
    "AGUILoadingStackedEarlier",
  );
  const hiddenCount =
    maxVisible != null && maxVisible > 0 ? Math.max(0, state.stepOrder.length - maxVisible) : 0;

  if (view === "summary" || hiddenCount === 0) return null;

  return <span {...props}>+{hiddenCount} earlier</span>;
}

import type { ComponentProps, ReactNode } from "react";

import { stackedStepValue, type AGUILoadingStackedByEvent } from "../../..";
import { cn } from "../cn";

import { AGUI_LOADING_WAITING_ICON } from "../agui-loading-waiting-icon";
import { useAGUILoadingStackedStep } from "./agui-loading-stacked-steps";

// -----
// Default icons. They use the text color, so you
// color them from the row, e.g.
// data-[status=done]:text-emerald-500.
// -----
const BUSY_ICON = (
  <span className="inline-block size-3 shrink-0 animate-spin rounded-full border-2 border-current border-t-transparent" />
);

const DONE_ICON = (
  <svg viewBox="0 0 16 16" className="size-3 shrink-0">
    <path
      d="M3.5 8.5l3 3 6-7"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const FAILED_ICON = (
  <svg viewBox="0 0 16 16" className="size-3 shrink-0">
    <circle cx="8" cy="8" r="6.5" fill="none" stroke="currentColor" strokeWidth="1.5" />
    <path d="M8 4.5v4M8 11v.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
  </svg>
);

export type AGUILoadingStackedStepIconProps = Omit<ComponentProps<"span">, "children"> & {
  // -----
  // Icon per row, keyed by the event that started the
  // row (RUN_STARTED, TOOL_CALL_START, ...) or "default".
  // A value can be a function of the step. Use null for no icon.
  // -----
  // While the row works.
  busyByEvent?: AGUILoadingStackedByEvent<ReactNode>;
  // When the row is finished.
  doneByEvent?: AGUILoadingStackedByEvent<ReactNode>;
  // When the row failed.
  failedByEvent?: AGUILoadingStackedByEvent<ReactNode>;
  // While the row waits for input.
  waitingByEvent?: AGUILoadingStackedByEvent<ReactNode>;
  // Icons for rows with no entry. Defaults: spinner, check, "!" circle, pause circle.
  busyFallback?: ReactNode;
  doneFallback?: ReactNode;
  failedFallback?: ReactNode;
  waitingFallback?: ReactNode;
};

// The icon for this row. It changes when the row waits, finishes or fails.
export function AGUILoadingStackedStepIcon({
  busyByEvent,
  doneByEvent,
  failedByEvent,
  waitingByEvent,
  busyFallback = BUSY_ICON,
  doneFallback = DONE_ICON,
  failedFallback = FAILED_ICON,
  waitingFallback = AGUI_LOADING_WAITING_ICON,
  className,
  ...props
}: AGUILoadingStackedStepIconProps) {
  const step = useAGUILoadingStackedStep("AGUILoadingStackedStepIcon");

  const [byEvent, fallback] =
    step.status === "done"
      ? [doneByEvent, doneFallback]
      : step.status === "failed"
        ? [failedByEvent, failedFallback]
        : step.status === "waiting"
          ? [waitingByEvent, waitingFallback]
          : [busyByEvent, busyFallback];
  const icon = stackedStepValue(step, byEvent);

  return (
    <span aria-hidden className={cn("inline-flex shrink-0", className)} {...props}>
      {icon === undefined ? fallback : icon}
    </span>
  );
}

import type { ComponentProps, ReactNode } from "react";

import { cn } from "../cn";

import { useAGUILoadingStackedStep } from "./agui-loading-stacked-steps";

export type AGUILoadingStackedStepSubagentProps = Omit<ComponentProps<"span">, "children"> & {
  // Shown after the name. Default "·".
  separator?: ReactNode;
};

// -----
// Name of the subagent this row's work belongs to.
// Nothing on the parent's rows or a subagent's own.
// -----
export function AGUILoadingStackedStepSubagent({
  separator = "·",
  className,
  ...props
}: AGUILoadingStackedStepSubagentProps) {
  const step = useAGUILoadingStackedStep("AGUILoadingStackedStepSubagent");

  if (step.kind === "subagent" || !step.subagentName) return null;

  return (
    <span className={cn("inline-flex items-center gap-1", className)} {...props}>
      <span>{step.subagentName}</span>
      <span aria-hidden>{separator}</span>
    </span>
  );
}

import type { ComponentProps } from "react";

import {
  STACKED_STEP_START_EVENT,
  stackedStepBusyTexts,
  stackedStepSettledText,
  stackedStepWaitingTexts,
  TEXT_ANIMATION_ROTATE_MS,
  type AGUILoadingStackedByEvent,
  type AGUILoadingTextAnimation,
} from "../../..";

import { AGUI_LOADING_CAPTION_TEXT_COMPONENTS } from "../animation/agui-loading-caption-text-components";
import { useAGUILoadingCaption } from "../use-agui-loading-caption";
import { useAGUILoadingStackedStep } from "./agui-loading-stacked-steps";

export type AGUILoadingStackedStepTextProps = Omit<ComponentProps<"span">, "children"> & {
  // -----
  // Text per row, keyed by the event that started the
  // row (RUN_STARTED, TOOL_CALL_START, ...) or "default".
  // A value can be a function of the step, e.g.
  // (step) => `Checked ${step.toolCallName}`.
  // Rows you don't list use the built-in text.
  // -----
  // Phrases that rotate while the row works.
  busyByEvent?: AGUILoadingStackedByEvent<readonly string[]>;
  // Text when the row is finished.
  doneByEvent?: AGUILoadingStackedByEvent<string>;
  // Text when the row failed.
  failedByEvent?: AGUILoadingStackedByEvent<string>;
  // Phrases that rotate while the row waits for input.
  waitingByEvent?: AGUILoadingStackedByEvent<readonly string[]>;
  // How the text changes: "slide-up" (default), "slide-down",
  // "slide-left", "slide-right", "typing" or "shuffle".
  animation?: AGUILoadingTextAnimation;
  // Milliseconds each phrase stays on screen.
  rotateEvery?: number;
};

// -----
// Rotates while the row works or waits, then shows
// its done or failed text. Spoken once, not per change.
// -----
export function AGUILoadingStackedStepText({
  busyByEvent,
  doneByEvent,
  failedByEvent,
  waitingByEvent,
  animation = "slide-up",
  rotateEvery,
  ...props
}: AGUILoadingStackedStepTextProps) {
  const step = useAGUILoadingStackedStep("AGUILoadingStackedStepText");
  const openingEvent = STACKED_STEP_START_EVENT[step.kind];
  const waiting = step.status === "waiting";
  const busyTexts = waiting
    ? stackedStepWaitingTexts(step, waitingByEvent)
    : stackedStepBusyTexts(step, busyByEvent);
  // A new key starts a new deck when the row starts or stops waiting.
  const captionKey = waiting ? "waiting" : openingEvent;

  const rotating = useAGUILoadingCaption({
    active: step.status === "active" || waiting,
    eventType: captionKey,
    rotateEvery: rotateEvery ?? TEXT_ANIMATION_ROTATE_MS[animation],
    textsByEvent: { [captionKey]: busyTexts },
  });
  const settled = stackedStepSettledText(step, {
    doneTextsByEvent: doneByEvent,
    failedTextsByEvent: failedByEvent,
  });
  const CaptionText = AGUI_LOADING_CAPTION_TEXT_COMPONENTS[animation];

  return (
    <span {...props}>
      <span aria-hidden>
        <CaptionText text={settled ?? rotating} />
      </span>
      <span className="sr-only">{settled ?? busyTexts[0]}</span>
    </span>
  );
}

import { createContext, use, type ComponentProps, type ReactNode } from "react";

import { AnimatePresence, motion } from "motion/react";

import { SLIDE_DURATION_MS, type AGUILoadingStackedStep } from "../../..";
import { cn } from "../cn";

import { useAGUILoadingStackedContext } from "./agui-loading-stacked";

const ROW_TRANSITION = { duration: SLIDE_DURATION_MS / 1000, ease: "easeOut" } as const;

const AGUILoadingStackedStepContext = createContext<AGUILoadingStackedStep | null>(
  null,
);

// The row's step. Throws if a row part is used outside Steps.
export function useAGUILoadingStackedStep(part: string) {
  const step = use(AGUILoadingStackedStepContext);
  if (!step) throw new Error(`${part} must be inside AGUILoadingStackedSteps`);
  return step;
}

export type AGUILoadingStackedStepsProps = Omit<ComponentProps<"ol">, "children"> & {
  // The row. It repeats one time for each step.
  children: ReactNode;
  // Classes for each row. Style rows with data-status and data-kind.
  rowClassName?: string;
  // Slide new rows in and fade old rows out. Default true.
  animate?: boolean;
};

// -----
// One row per step, with data-status, data-kind and
// data-subagent (the subagent the row belongs to).
// -----
export function AGUILoadingStackedSteps({
  children,
  rowClassName,
  animate = true,
  className,
  ...props
}: AGUILoadingStackedStepsProps) {
  const { state, view, maxVisible } = useAGUILoadingStackedContext(
    "AGUILoadingStackedSteps",
  );

  if (view === "summary") return null;

  const visibleIds =
    maxVisible != null && maxVisible > 0 ? state.stepOrder.slice(-maxVisible) : state.stepOrder;

  const rows = visibleIds.map((id) => {
    const step = state.steps[id]!;
    // A subagent's own row belongs to the subagent that started it.
    const owner = step.kind === "subagent" ? step.parentSubagentRunId : step.subagentRunId;
    const rowProps = {
      "data-status": step.status,
      "data-kind": step.kind,
      "data-subagent": owner ?? undefined,
      className: cn("flex items-center gap-2", rowClassName),
    };
    const row = (
      <AGUILoadingStackedStepContext value={step}>{children}</AGUILoadingStackedStepContext>
    );

    return animate ? (
      <motion.li
        key={id}
        layout
        initial={{ opacity: 0, y: 6 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, height: 0 }}
        transition={ROW_TRANSITION}
        {...rowProps}
      >
        {row}
      </motion.li>
    ) : (
      <li key={id} {...rowProps}>
        {row}
      </li>
    );
  });

  return (
    <ol className={cn("flex flex-col gap-1.5", className)} {...props}>
      {animate ? <AnimatePresence initial={false}>{rows}</AnimatePresence> : rows}
    </ol>
  );
}

import type { ComponentProps } from "react";

import { stackedStepCount, stackedSummaryText } from "../../..";
import { cn } from "../cn";

import { useAGUILoadingStackedContext } from "./agui-loading-stacked";

export type AGUILoadingStackedSummaryProps = ComponentProps<"span"> & {
  // Fixed text, or a function that gets the number of steps.
  text?: string | ((steps: number) => string);
};

// Shows only after the rows fold, and only for this result.
function AGUILoadingStackedSummary({
  part,
  result,
  text,
  children,
  className,
  ...props
}: AGUILoadingStackedSummaryProps & { part: string; result: "done" | "failed" }) {
  const { state, view } = useAGUILoadingStackedContext(part);

  // A stopped run folds into the failed summary.
  const outcome = state.status === "stopped" ? "failed" : state.status;
  if (view !== "summary" || outcome !== result) return null;

  const summary =
    text === undefined
      ? stackedSummaryText(state)
      : typeof text === "function"
        ? text(stackedStepCount(state))
        : text;

  return (
    <span className={cn("flex items-center gap-2", className)} {...props}>
      {children}
      {summary}
    </span>
  );
}

// -----
// One line after a finished run folds (whenDone="collapse").
// Default text: "Finished · 4 steps". Put an icon
// in children; it shows before the text.
// -----
export function AGUILoadingStackedSummaryDone(
  props: AGUILoadingStackedSummaryProps,
) {
  return (
    <AGUILoadingStackedSummary
      part="AGUILoadingStackedSummaryDone"
      result="done"
      {...props}
    />
  );
}

// -----
// One line after a failed or stopped run folds.
// Default text: "Stopped · 4 steps".
// -----
export function AGUILoadingStackedSummaryFailed(
  props: AGUILoadingStackedSummaryProps,
) {
  return (
    <AGUILoadingStackedSummary
      part="AGUILoadingStackedSummaryFailed"
      result="failed"
      {...props}
    />
  );
}

import { createContext, use, type ComponentProps } from "react";

import type { AGUILoadingStackedState } from "../../..";
import { cn } from "../cn";

import { useAGUILoadingPresence } from "../use-agui-loading-presence";

// "steps": show the rows. "summary": the run ended and folded into one line.
type AGUILoadingStackedView = "steps" | "summary";

type AGUILoadingStackedContextValue = {
  state: AGUILoadingStackedState;
  view: AGUILoadingStackedView;
  maxVisible: number | undefined;
};

const AGUILoadingStackedContext =
  createContext<AGUILoadingStackedContextValue | null>(null);

// Shared state for the parts. Throws if a part is used outside the root.
export function useAGUILoadingStackedContext(part: string) {
  const context = use(AGUILoadingStackedContext);
  if (!context) throw new Error(`${part} must be inside AGUILoadingStacked`);
  return context;
}

// -----
// What happens when the agent finishes.
// lingerMs can only be set with "collapse" or "hide".
// -----
type AGUILoadingStackedWhenDoneProps =
  | {
      // "keep" (default): the finished rows stay on screen.
      whenDone?: "keep";
      lingerMs?: never;
    }
  | {
      // "collapse": after lingerMs, fold the rows into the summary.
      // "hide": after lingerMs, hide everything.
      whenDone: "collapse" | "hide";
      // How long the finished rows stay first. Default 1200.
      lingerMs?: number;
    };

export type AGUILoadingStackedProps = Omit<ComponentProps<"div">, "role"> & {
  // From aguiLoadingStackedReducer.
  state: AGUILoadingStackedState;
  // Show only the newest N rows. The Earlier part counts the rest.
  maxVisible?: number;
} & AGUILoadingStackedWhenDoneProps;

// -----
// Root of the stacked loader. Style it with data-status:
// running, waiting, done, failed or stopped.
// -----
export function AGUILoadingStacked({
  state,
  maxVisible,
  whenDone = "keep",
  lingerMs,
  className,
  children,
  ...props
}: AGUILoadingStackedProps) {
  const running = state.status === "running";
  const waiting = state.status === "waiting";
  const presence = useAGUILoadingPresence(
    running,
    { whenDone: whenDone === "keep" ? "keep" : "linger", lingerMs },
    waiting,
  );

  if (state.status === "idle") return null;

  // The linger is over: fold into the summary, or hide. A waiting run stays.
  const lingerOver = !running && !waiting && presence === "hidden";
  if (lingerOver && whenDone === "hide") return null;
  const view = lingerOver && whenDone === "collapse" ? "summary" : "steps";

  return (
    <AGUILoadingStackedContext value={{ state, view, maxVisible }}>
      <div
        role="status"
        aria-busy={running}
        data-status={state.status}
        data-view={view}
        className={cn("flex flex-col gap-1.5", className)}
        {...props}
      >
        {children}
      </div>
    </AGUILoadingStackedContext>
  );
}

export {
  AGUILoadingStacked,
  type AGUILoadingStackedProps,
} from "./agui-loading-stacked";
export {
  AGUILoadingStackedSteps,
  type AGUILoadingStackedStepsProps,
} from "./agui-loading-stacked-steps";
export {
  AGUILoadingStackedStepIcon,
  type AGUILoadingStackedStepIconProps,
} from "./agui-loading-stacked-step-icon";
export {
  AGUILoadingStackedStepSubagent,
  type AGUILoadingStackedStepSubagentProps,
} from "./agui-loading-stacked-step-subagent";
export {
  AGUILoadingStackedStepText,
  type AGUILoadingStackedStepTextProps,
} from "./agui-loading-stacked-step-text";
export {
  AGUILoadingStackedEarlier,
  type AGUILoadingStackedEarlierProps,
} from "./agui-loading-stacked-earlier";
export {
  AGUILoadingStackedSummaryDone,
  AGUILoadingStackedSummaryFailed,
  type AGUILoadingStackedSummaryProps,
} from "./agui-loading-stacked-summary";

// -----
// Paused circle for a run that waits for input.
// It never spins: nothing is working.
// -----
export const AGUI_LOADING_WAITING_ICON = (
  <svg viewBox="0 0 16 16" className="size-3 shrink-0">
    <circle cx="8" cy="8" r="6.5" fill="none" stroke="currentColor" strokeWidth="1.5" />
    <path d="M6.5 5.5v5M9.5 5.5v5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
  </svg>
);

import type { ComponentProps } from "react";

import { useAGUILoadingContext } from "./agui-loading";

export type AGUILoadingEventProps = Omit<ComponentProps<"span">, "children">;

// -----
// The name of the latest event, e.g. TOOL_CALL_START.
// Shows nothing before the first event.
// -----
export function AGUILoadingEvent(props: AGUILoadingEventProps) {
  const { eventType } = useAGUILoadingContext("AGUILoadingEvent");

  if (eventType == null) return null;

  return (
    <span aria-hidden {...props}>
      {eventType}
    </span>
  );
}

import type { ComponentProps, ReactNode } from "react";

import {
  valueForEventType,
  type AGUILoadingByEvent,
  type AGUILoadingStatusKey,
  type EventType,
} from "../../..";
import { cn } from "../cn";

import { AGUI_LOADING_WAITING_ICON } from "../agui-loading-waiting-icon";
import { useAGUILoadingContext } from "./agui-loading";

// Spinning circle, used when no icon is given.
const DEFAULT_FALLBACK = (
  <span className="inline-block size-3 shrink-0 animate-spin rounded-full border-2 border-current border-t-transparent" />
);

export type AGUILoadingIconProps<TEvent extends string = EventType> = Omit<
  ComponentProps<"span">,
  "children"
> & {
  // Icon per event, plus "waiting" and "stopped". Use null to show no icon.
  byEvent?: AGUILoadingByEvent<ReactNode, TEvent>;
  // Icon for events with no entry in byEvent. Default: a spinner.
  fallback?: ReactNode;
  // Icon while the run waits, if byEvent has no "waiting". Default: a pause circle.
  waitingFallback?: ReactNode;
};

// -----
// The icon for the latest event. Its animation freezes
// when the run ends; a waiting run shows a pause icon.
// -----
export function AGUILoadingIcon<TEvent extends string = EventType>({
  byEvent,
  fallback = DEFAULT_FALLBACK,
  waitingFallback = AGUI_LOADING_WAITING_ICON,
  className,
  ...props
}: AGUILoadingIconProps<TEvent>) {
  const { captionKey, presence } = useAGUILoadingContext("AGUILoadingIcon");
  const icon = valueForEventType(captionKey as TEvent | AGUILoadingStatusKey | null, byEvent);
  const ended = presence === "lingering" || presence === "done";
  const shownFallback = presence === "waiting" ? waitingFallback : fallback;

  return (
    <span
      aria-hidden
      className={cn(
        "inline-flex shrink-0",
        ended && "**:[animation-play-state:paused]",
        className,
      )}
      {...props}
    >
      {icon === undefined ? shownFallback : icon}
    </span>
  );
}

import type { ComponentProps, ReactNode } from "react";

import { cn } from "../cn";

import { useAGUILoadingContext } from "./agui-loading";

export type AGUILoadingSubagentProps = Omit<ComponentProps<"span">, "children"> & {
  // Shown after the name. Default "·".
  separator?: ReactNode;
};

// -----
// Name of the subagent behind the latest event.
// Nothing while the parent agent works.
// -----
export function AGUILoadingSubagent({
  separator = "·",
  className,
  ...props
}: AGUILoadingSubagentProps) {
  const { subagent } = useAGUILoadingContext("AGUILoadingSubagent");

  if (!subagent) return null;

  return (
    <span className={cn("inline-flex items-center gap-1", className)} {...props}>
      <span>{subagent}</span>
      <span aria-hidden>{separator}</span>
    </span>
  );
}

import type { ComponentProps } from "react";

import {
  TEXT_ANIMATION_ROTATE_MS,
  textsForEventType,
  type AGUILoadingStatusKey,
  type AGUILoadingTextAnimation,
  type AGUILoadingTextsByEvent,
  type EventType,
} from "../../..";

import { AGUI_LOADING_CAPTION_TEXT_COMPONENTS } from "../animation/agui-loading-caption-text-components";
import { useAGUILoadingCaption } from "../use-agui-loading-caption";
import { useAGUILoadingContext } from "./agui-loading";

export type AGUILoadingTextProps<TEvent extends string = EventType> = Omit<
  ComponentProps<"span">,
  "children"
> & {
  // Phrases to show per event, plus "waiting" and "stopped".
  // Unlisted keys use the built-in text.
  byEvent?: AGUILoadingTextsByEvent<TEvent>;
  // How the text changes: "slide-up" (default), "slide-down",
  // "slide-left", "slide-right", "typing" or "shuffle".
  animation?: AGUILoadingTextAnimation;
  // Milliseconds each phrase stays on screen.
  rotateEvery?: number;
};

// -----
// Text for the latest event. It rotates while the
// agent works or waits; screen readers hear it once.
// -----
export function AGUILoadingText<TEvent extends string = EventType>({
  byEvent,
  animation = "slide-up",
  rotateEvery,
  ...props
}: AGUILoadingTextProps<TEvent>) {
  const { active, waiting, captionKey } = useAGUILoadingContext("AGUILoadingText");
  const key = captionKey as TEvent | AGUILoadingStatusKey | null;
  const text = useAGUILoadingCaption({
    active: active || waiting,
    eventType: key,
    rotateEvery: rotateEvery ?? TEXT_ANIMATION_ROTATE_MS[animation],
    textsByEvent: byEvent,
  });
  const spokenText = textsForEventType(key, byEvent)[0];
  const CaptionText = AGUI_LOADING_CAPTION_TEXT_COMPONENTS[animation];

  return (
    <span {...props}>
      <span aria-hidden>
        <CaptionText text={text} />
      </span>
      <span className="sr-only">{spokenText}</span>
    </span>
  );
}

import { createContext, use, type ComponentProps } from "react";

import type { AGUILoadingPresence, AGUILoadingStatusKey, AGUILoadingWhenDone } from "../../..";
import { cn } from "../cn";

import { useAGUILoadingPresence } from "../use-agui-loading-presence";

type AGUILoadingContextValue = {
  active: boolean;
  waiting: boolean;
  eventType: string | null;
  captionKey: string | AGUILoadingStatusKey | null;
  subagent: string | null;
  presence: AGUILoadingPresence;
};

const AGUILoadingContext = createContext<AGUILoadingContextValue | null>(null);

// Shared state for the parts. Throws if a part is used outside the root.
export function useAGUILoadingContext(part: string) {
  const context = use(AGUILoadingContext);
  if (!context) throw new Error(`${part} must be inside AGUILoading`);
  return context;
}

// -----
// What happens when the agent finishes.
// lingerMs can only be set with "linger".
// -----
type AGUILoadingWhenDoneProps =
  | {
      // "linger" (default): show the last text, then hide.
      whenDone?: Extract<AGUILoadingWhenDone, "linger">;
      // How long to show the last text. Default 1200. 0 hides right away.
      lingerMs?: number;
    }
  | {
      // "hide": hide right away.
      // "keep": show the last text until the next run.
      whenDone: Exclude<AGUILoadingWhenDone, "linger">;
      lingerMs?: never;
    };

export type AGUILoadingProps = Omit<ComponentProps<"div">, "role"> & {
  // true while the agent is working.
  active: boolean;
  // The latest event. Picks which text and icon the parts show.
  eventType: string | null;
  // true while the run waits for input (state.status === "waiting").
  waiting?: boolean;
  // true when the run was cancelled (state.status === "stopped").
  stopped?: boolean;
  // Name of the subagent that sent the latest event (state.subagentName).
  subagent?: string | null;
} & AGUILoadingWhenDoneProps;

// -----
// Root of the loader; parts go inside in any order.
// data-presence: running, waiting, lingering, done.
// -----
export function AGUILoading({
  active,
  eventType,
  waiting = false,
  stopped = false,
  subagent = null,
  whenDone,
  lingerMs,
  className,
  children,
  ...props
}: AGUILoadingProps) {
  const presence = useAGUILoadingPresence(active, { whenDone, lingerMs }, waiting);

  if (presence === "hidden") return null;

  // -----
  // Waiting and stopped have their own captions and
  // icons, keyed "waiting" and "stopped".
  // -----
  const captionKey = waiting ? "waiting" : stopped && !active ? "stopped" : eventType;

  return (
    <AGUILoadingContext value={{ active, waiting, eventType, captionKey, subagent, presence }}>
      <div
        role="status"
        aria-busy={presence === "running"}
        data-presence={presence}
        className={cn("flex items-center gap-2", className)}
        {...props}
      >
        {children}
      </div>
    </AGUILoadingContext>
  );
}

