    "Scanning",
    "Observing",
    "Taking stock",
  ],
  [EventType.ACTIVITY_DELTA]: [
    "Tracking",
    "Noting",
    "Logging",
    "Recording",
    "Watching",
  ],
  [EventType.RAW]: [
    "Passing through",
    "Relaying",
    "Forwarding",
    "Routing",
    "Handling",
  ],
  [EventType.CUSTOM]: [
    "Finishing up",
    "Putting it together",
    "Wrapping up",
    "Finalizing",
    "Polishing off",
  ],
  [WAITING_LOADING_TEXTS_KEY]: [
    "Waiting",
    "Waiting on you",
    "Standing by",
    "Holding",
    "Needs your input",
  ],
  [STOPPED_LOADING_TEXTS_KEY]: [
    "Stopped",
    "Halted",
    "Called off",
    "Cut short",
    "Ended early",
  ],
  [DEFAULT_LOADING_TEXTS_KEY]: [
    "Working",
    "Processing",
    "Preparing",
    "Loading",
    "In progress",
  ],
} satisfies Record<
  EventType | AGUILoadingStatusKey | typeof DEFAULT_LOADING_TEXTS_KEY,
  readonly string[]
>;

// -----
// LOADING_TEXTS_BY_EVENT only ever holds real AG-UI
// keys, so a widened, non-AG-UI TEvent key just misses
// it and falls through to overrides/default — the cast
// only relaxes the lookup, not what's actually in the map.
// -----
export function textsForEventType<TEvent extends string>(
  eventType: TEvent | AGUILoadingStatusKey | null,
  overrides: AGUILoadingTextsByEvent<TEvent> | undefined,
): readonly string[] {
  const key = eventType ?? DEFAULT_LOADING_TEXTS_KEY;
  // SAFETY: indexing with a TEvent key that isn't a real EventType member
  // just misses this object (returns undefined), which the ?? chain below
  // already handles — the cast only widens the key type, not the values.
  const builtIn = LOADING_TEXTS_BY_EVENT as AGUILoadingTextsByEvent<TEvent> & {
    [DEFAULT_LOADING_TEXTS_KEY]: readonly string[];
  };
  return (
    overrides?.[key] ??
    builtIn[key] ??
    overrides?.[DEFAULT_LOADING_TEXTS_KEY] ??
    builtIn[DEFAULT_LOADING_TEXTS_KEY]
  );
}

export function shuffle(items: readonly string[]): string[] {
  const deck = [...items];
  for (let i = deck.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const swap = deck[i]!;
    deck[i] = deck[j]!;
    deck[j] = swap;
  }
  return deck;
}

import { EventType } from "@ag-ui/core";

// -----
// Pure AG-UI loader state machine. No DOM, no
// fetch, no timers — a (state, event) => state
// reducer that can lift straight into a real
// hook once the model is validated. Everything
// below is real @ag-ui/core event shapes, not a
// simplified stand-in.
// -----

// -----
// Re-exported so adapters import EventType from
// core instead of depending on @ag-ui/core directly.
// -----
export { EventType };

export type AGUILoadingSubagentTag = { subagentRunId?: string };

export type AGUILoadingInterrupt = {
  id: string;
  subagentRunId?: string;
  toolCallId?: string;
  message?: string;
};

export type AGUILoadingResumeEntry = {
  interruptId: string;
  status: "resolved" | "cancelled";
};

export type AGUILoadingRunOutcome =
  | { type: "success"; pendingToolCallIds?: string[] }
  | { type: "interrupt"; interrupts: AGUILoadingInterrupt[] }
  | { type: "cancelled" };

export type AGUILoadingSubagentOutcome =
  | { type: "success" }
  | { type: "suspended"; interruptIds?: string[] };

export type AGUILoadingStreamEvent =
  | {
      type: EventType.RUN_STARTED;
      runId: string;
      threadId?: string;
      parentRunId?: string;
      input?: { resume?: AGUILoadingResumeEntry[] };
    }
  | ({ type: EventType.TEXT_MESSAGE_START; messageId: string; role: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.TEXT_MESSAGE_CONTENT; messageId: string; delta: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.TEXT_MESSAGE_END; messageId: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.TOOL_CALL_START; toolCallId: string; toolCallName: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.TOOL_CALL_RESULT; toolCallId: string; content: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.TOOL_CALL_END; toolCallId: string } & AGUILoadingSubagentTag)
  | { type: EventType.RUN_FINISHED; runId: string; outcome?: AGUILoadingRunOutcome }
  | { type: EventType.RUN_ERROR; message: string; code?: string }
  | {
      type: EventType.SUBAGENT_STARTED;
      subagentRunId: string;
      name: string;
      description?: string;
      parentSubagentRunId?: string;
      parentToolCallId?: string;
    }
  | {
      type: EventType.SUBAGENT_FINISHED;
      subagentRunId: string;
      outcome?: AGUILoadingSubagentOutcome;
    }
  | { type: EventType.SUBAGENT_ERROR; subagentRunId: string; message: string; code?: string };

export type LoadingStatus = "idle" | "running" | "waiting" | "done" | "failed" | "stopped";

export type LoadingMessage = {
  role: string;
  text: string;
  done: boolean;
};

export type LoadingToolCall = {
  toolCallName: string;
  result: string | null;
};

export type AGUILoadingState = {
  status: LoadingStatus;
  runId: string | null;
  lastEventType: EventType | null;
  messages: Record<string, LoadingMessage>;
  messageOrder: string[];
  toolCalls: Record<string, LoadingToolCall>;
  toolCallOrder: string[];
  error: { message: string; code?: string } | null;
  subagentName: string | null;
  subagentNames: Record<string, string>;
  subagentParentIds: Record<string, string>;
  interruptIds: string[];
};

export const initialAGUILoadingState: AGUILoadingState = {
  status: "idle",
  runId: null,
  lastEventType: null,
  messages: {},
  messageOrder: [],
  toolCalls: {},
  toolCallOrder: [],
  error: null,
  subagentName: null,
  subagentNames: {},
  subagentParentIds: {},
  interruptIds: [],
};

// -----
// A run that has finished or errored is over —
// the protocol has nothing left to say. Late
// events (a straggling delta, a retried tool
// call) are dropped instead of reopening state,
// which is the bug the original hook had: its
// "delta" case set status back to "loading"
// unconditionally, no matter what came before.
// -----
function isTerminal(state: AGUILoadingState): boolean {
  return state.status === "done" || state.status === "failed" || state.status === "stopped";
}

type RunStartedEvent = Extract<AGUILoadingStreamEvent, { type: EventType.RUN_STARTED }>;

// -----
// A resume entry for one of our interrupts, else
// (no input echoed) parentRunId naming our run.
// -----
export function continuesWaitingRun(
  waiting: { status: LoadingStatus; runId: string | null; interruptIds: string[] },
  event: RunStartedEvent,
): boolean {
  if (waiting.status !== "waiting") return false;
  const resume = event.input?.resume;
  if (resume?.length) return resume.some((entry) => waiting.interruptIds.includes(entry.interruptId));
  return event.parentRunId !== undefined && event.parentRunId === waiting.runId;
}

// -----
// The name of a subagent run, or null for
// the parent agent (no id).
// -----
function findSubagentName(state: AGUILoadingState, id: string | undefined): string | null {
  return id === undefined ? null : (state.subagentNames[id] ?? null);
}

// -----
// Only a new run gets past a waiting one. Other
// events name their owner in subagentName.
// -----
export function aguiLoadingReducer(
  state: AGUILoadingState,
  event: AGUILoadingStreamEvent,
): AGUILoadingState {
  if (isTerminal(state)) return state;
  if (state.status === "waiting" && event.type !== EventType.RUN_STARTED) return state;

  const next = reduceStreamEvent(state, event);
  if (event.type === EventType.RUN_STARTED || next.status === "waiting") return next;
  if (event.type === EventType.RUN_FINISHED || event.type === EventType.RUN_ERROR) {
    return { ...next, subagentName: null };
  }
  // -----
  // A finished subagent hands the line back to
  // whoever started it: a parent subagent, or none.
  // -----
  if (event.type === EventType.SUBAGENT_FINISHED && event.outcome?.type !== "suspended") {
    const parentId = next.subagentParentIds[event.subagentRunId];
    return { ...next, subagentName: findSubagentName(next, parentId) };
  }
  const ownerId = "subagentRunId" in event ? event.subagentRunId : undefined;
  return { ...next, subagentName: findSubagentName(next, ownerId) };
}

function reduceStreamEvent(
  state: AGUILoadingState,
  event: AGUILoadingStreamEvent,
): AGUILoadingState {
  switch (event.type) {
    case EventType.RUN_STARTED:
      if (continuesWaitingRun(state, event)) {
        return {
          ...state,
          status: "running",
          runId: event.runId,
          lastEventType: event.type,
          interruptIds: [],
          subagentName: null,
        };
      }
      return {
        ...initialAGUILoadingState,
        status: "running",
        runId: event.runId,
        lastEventType: event.type,
      };

    case EventType.SUBAGENT_STARTED:
      return {
        ...state,
        lastEventType: event.type,
        subagentNames: { ...state.subagentNames, [event.subagentRunId]: event.name },
        subagentParentIds:
          event.parentSubagentRunId === undefined
            ? state.subagentParentIds
            : { ...state.subagentParentIds, [event.subagentRunId]: event.parentSubagentRunId },
      };

    case EventType.SUBAGENT_FINISHED:
    case EventType.SUBAGENT_ERROR:
      return { ...state, lastEventType: event.type };

    case EventType.TEXT_MESSAGE_START: {
      if (state.messages[event.messageId]) {
        return { ...state, lastEventType: event.type };
      }
      return {
        ...state,
        lastEventType: event.type,
        messages: {
          ...state.messages,
          [event.messageId]: { role: event.role, text: "", done: false },
        },
        messageOrder: [...state.messageOrder, event.messageId],
      };
    }

    case EventType.TEXT_MESSAGE_CONTENT: {
      // -----
      // Every messageId gets its own buffer. The
      // original hook locked onto whichever message
      // first streamed a `{` and silently dropped
      // deltas for any other id — a preamble message
      // plus the structured answer in the same run
      // would lose one of them.
      // -----
      const existing = state.messages[event.messageId] ?? {
        role: "assistant",
        text: "",
        done: false,
      };
      if (existing.done) return { ...state, lastEventType: event.type };
      return {
        ...state,
        lastEventType: event.type,
        messages: {
          ...state.messages,
          [event.messageId]: { ...existing, text: existing.text + event.delta },
        },
        messageOrder: state.messageOrder.includes(event.messageId)
          ? state.messageOrder
          : [...state.messageOrder, event.messageId],
      };
    }

    case EventType.TEXT_MESSAGE_END: {
      const existing = state.messages[event.messageId];
      if (!existing) return { ...state, lastEventType: event.type };
      return {
        ...state,
        lastEventType: event.type,
        messages: {
          ...state.messages,
          [event.messageId]: { ...existing, done: true },
        },
      };
    }

    case EventType.TOOL_CALL_START: {
      // -----
      // Additive by toolCallId. The original hook
      // reset its whole communications[] list on every
      // TOOL_CALL_START, so a second tool call in the
      // same run wiped out the first call's result.
      // -----
      return {
        ...state,
        lastEventType: event.type,
        toolCalls: {
          ...state.toolCalls,
          [event.toolCallId]: { toolCallName: event.toolCallName, result: null },
        },
        toolCallOrder: state.toolCallOrder.includes(event.toolCallId)
          ? state.toolCallOrder
          : [...state.toolCallOrder, event.toolCallId],
      };
    }

    case EventType.TOOL_CALL_RESULT: {
      const existing = state.toolCalls[event.toolCallId];
      return {
        ...state,
        lastEventType: event.type,
        toolCalls: {
          ...state.toolCalls,
          [event.toolCallId]: {
            toolCallName: existing?.toolCallName ?? "unknown",
            result: event.content,
          },
        },
        toolCallOrder: state.toolCallOrder.includes(event.toolCallId)
          ? state.toolCallOrder
          : [...state.toolCallOrder, event.toolCallId],
      };
    }

    case EventType.TOOL_CALL_END:
      return { ...state, lastEventType: event.type };

    case EventType.RUN_FINISHED: {
      // -----
      // Completion is the protocol's own signal. An
      // interrupt waits for input; cancelled stops.
      // -----
      const outcome = event.outcome;
      if (outcome?.type === "interrupt") {
        const waitingSubagent = outcome.interrupts.find((i) => i.subagentRunId)?.subagentRunId;
        return {
          ...state,
          status: "waiting",
          lastEventType: event.type,
          interruptIds: outcome.interrupts.map((interrupt) => interrupt.id),
          subagentName: waitingSubagent ? (state.subagentNames[waitingSubagent] ?? null) : null,
        };
      }
      const status = outcome?.type === "cancelled" ? "stopped" : "done";
      return { ...state, status, lastEventType: event.type };
    }

    case EventType.RUN_ERROR:
      // -----
      // The bug this exists to fix: the original hook
      // had no RUN_ERROR branch at all, so a mid-stream
      // error left status stuck on "loading" forever.
      // -----
      return {
        ...state,
        status: "failed",
        lastEventType: event.type,
        error: { message: event.message, code: event.code },
      };

    default:
      return state;
  }
}

// -----
// Whether the loader is on screen. What happens when
// a run ends is set by whenDone:
//   "hide"   — gone on the same render
//   "linger" — stays lingerMs on its final caption
//              ("Wrapping up", or the RUN_ERROR one),
//              then hides. Adapters own the timeout.
//   "keep"   — stays on its final caption until the
//              next run replaces it
// -----

export type AGUILoadingPresence = "hidden" | "running" | "waiting" | "lingering" | "done";

export type AGUILoadingWhenDone = "hide" | "linger" | "keep";

export const LINGER_MS = 1200;

export type AGUILoadingPresenceOptions = {
  whenDone?: AGUILoadingWhenDone;
  // Only read when whenDone is "linger". 0 hides immediately.
  lingerMs?: number;
};

export function initialAGUILoadingPresence(
  active: boolean,
  waiting = false,
): AGUILoadingPresence {
  if (active) return "running";
  return waiting ? "waiting" : "hidden";
}

// -----
// A waiting run stays until the next run, whatever
// whenDone says. Only a showing loader winds down.
// -----
export function presenceOnActiveChange(
  presence: AGUILoadingPresence,
  active: boolean,
  { whenDone = "linger", lingerMs = LINGER_MS }: AGUILoadingPresenceOptions = {},
  waiting = false,
): AGUILoadingPresence {
  if (active) return "running";
  if (waiting) return "waiting";
  if (presence !== "running" && presence !== "waiting") return presence;
  if (whenDone === "keep") return "done";
  if (whenDone === "linger" && lingerMs > 0) return "lingering";
  return "hidden";
}

export function presenceOnLingerElapsed(
  presence: AGUILoadingPresence,
): AGUILoadingPresence {
  return presence === "lingering" ? "hidden" : presence;
}

import { valueForEventType } from "./agui-loading-by-event";
import {
  DEFAULT_LOADING_TEXTS_KEY,
  textsForEventType,
  WAITING_LOADING_TEXTS_KEY,
} from "./agui-loading-captions";
import type {
  AGUILoadingStackedState,
  AGUILoadingStackedStep,
  AGUILoadingStackedStepKind,
} from "./agui-loading-stacked-machine";
import { EventType } from "./agui-loading-machine";

// -----
// Every stacked map value is either a plain value or
// a function of the row — e.g. pick an icon or text
// from step.toolCallName. Plain values stay the
// simple case; the function is there when you need it.
// -----
export type AGUILoadingStackedStepValue<TValue> =
  | TValue
  | ((step: AGUILoadingStackedStep) => TValue);

export type AGUILoadingStackedStepTextValue = AGUILoadingStackedStepValue<string>;

// -----
// Keyed by the event that OPENED the row, not its
// latest one — a tool row goes START → ARGS → END →
// RESULT, so keying by the latest event would flip
// its icon and captions mid-row. Only these six open
// rows (RUN_ERROR opens the error row); keying
// anything else is a type error, not a silent miss.
// -----
export type AGUILoadingStackedStartEvent =
  | EventType.RUN_STARTED
  | EventType.TOOL_CALL_START
  | EventType.TEXT_MESSAGE_START
  | EventType.REASONING_START
  | EventType.SUBAGENT_STARTED
  | EventType.RUN_ERROR;

export const STACKED_STEP_START_EVENT = {
  run: EventType.RUN_STARTED,
  tool: EventType.TOOL_CALL_START,
  message: EventType.TEXT_MESSAGE_START,
  reasoning: EventType.REASONING_START,
  subagent: EventType.SUBAGENT_STARTED,
  error: EventType.RUN_ERROR,
} as const satisfies Record<AGUILoadingStackedStepKind, AGUILoadingStackedStartEvent>;

// -----
// The shape of every stacked ...ByEvent prop (busy,
// done, failed; texts and icons): opening events plus
// "default", each a value or a function of the row.
// -----
export type AGUILoadingStackedByEvent<TValue> = Partial<
  Record<
    AGUILoadingStackedStartEvent | typeof DEFAULT_LOADING_TEXTS_KEY,
    AGUILoadingStackedStepValue<TValue>
  >
>;

// -----
// The row's opening-event entry, else "default", else
// undefined — with a function entry already called on
// the row. An explicit null entry comes back as null.
// -----
export function stackedStepValue<TValue>(
  step: AGUILoadingStackedStep,
  byEvent: AGUILoadingStackedByEvent<TValue> | undefined,
): TValue | undefined {
  const entry = valueForEventType(STACKED_STEP_START_EVENT[step.kind], byEvent);
  // SAFETY: values are never functions themselves (text, text lists,
  // React nodes), so a function entry is always the (step) => value form.
  return typeof entry === "function"
    ? (entry as (step: AGUILoadingStackedStep) => TValue)(step)
    : entry;
}

// -----
// Captions for a busy row: yours, else ones that
// name the subagent, else the built-in ones.
// -----
export function stackedStepBusyTexts(
  step: AGUILoadingStackedStep,
  busyTextsByEvent: AGUILoadingStackedByEvent<readonly string[]> | undefined,
): readonly string[] {
  const custom = stackedStepValue(step, busyTextsByEvent);
  if (custom !== undefined) return custom;
  const name = step.kind === "subagent" ? step.subagentName : null;
  if (name) {
    return [
      `Delegating to ${name}`,
      `Handing off to ${name}`,
      `Briefing ${name}`,
      `Calling in ${name}`,
    ];
  }
  return textsForEventType(STACKED_STEP_START_EVENT[step.kind], undefined);
}

// -----
// Captions for a waiting row: yours, else ones that
// name the tool or subagent, else the waiting ones.
// -----
export function stackedStepWaitingTexts(
  step: AGUILoadingStackedStep,
  waitingTextsByEvent: AGUILoadingStackedByEvent<readonly string[]> | undefined,
): readonly string[] {
  const custom = stackedStepValue(step, waitingTextsByEvent);
  if (custom !== undefined) return custom;
  const name = step.kind === "subagent" ? step.subagentName : step.toolCallName;
  if (name) return [`${name} is waiting`, `${name} is on hold`, `${name} is standing by`];
  return textsForEventType(WAITING_LOADING_TEXTS_KEY, undefined);
}

export const LOADING_STACKED_DONE_TEXTS = {
  [EventType.RUN_STARTED]: "Started",
  [EventType.TOOL_CALL_START]: (step) =>
    step.toolCallName ? `Called ${step.toolCallName}` : "Called a tool",
  [EventType.TEXT_MESSAGE_START]: "Wrote a response",
  [EventType.REASONING_START]: "Thought it through",
  [EventType.SUBAGENT_STARTED]: (step) =>
    step.subagentName ? `Asked ${step.subagentName}` : "Asked a subagent",
  // The error row is always failed; this entry only completes the map.
  [EventType.RUN_ERROR]: "Something went wrong",
} satisfies Record<AGUILoadingStackedStartEvent, AGUILoadingStackedStepTextValue>;

export const LOADING_STACKED_FAILED_TEXTS = {
  [EventType.RUN_STARTED]: "Couldn't start",
  [EventType.TOOL_CALL_START]: (step) =>
    step.toolCallName ? `Stopped calling ${step.toolCallName}` : "Tool call stopped",
  [EventType.TEXT_MESSAGE_START]: "Response cut off",
  [EventType.REASONING_START]: "Stopped thinking",
  [EventType.SUBAGENT_STARTED]: (step) =>
    step.errorMessage || (step.subagentName ? `${step.subagentName} failed` : "Subagent failed"),
  [EventType.RUN_ERROR]: (step) => step.errorMessage || "Something went wrong",
} satisfies Record<AGUILoadingStackedStartEvent, AGUILoadingStackedStepTextValue>;

// -----
// Your text, else why it stopped, else built-in.
// Null for busy or waiting rows: those rotate.
// -----
export function stackedStepSettledText(
  step: AGUILoadingStackedStep,
  overrides?: {
    doneTextsByEvent?: AGUILoadingStackedByEvent<string>;
    failedTextsByEvent?: AGUILoadingStackedByEvent<string>;
  },
): string | null {
  if (step.status === "active" || step.status === "waiting") return null;
  const [custom, builtIn] =
    step.status === "done"
      ? [overrides?.doneTextsByEvent, LOADING_STACKED_DONE_TEXTS]
      : [overrides?.failedTextsByEvent, LOADING_STACKED_FAILED_TEXTS];
  const customText = stackedStepValue(step, custom);
  if (customText !== undefined) return customText;
  if (step.status === "failed" && step.failReason) {
    return step.failReason === "stopped" ? "Stopped" : "Cancelled";
  }
  const builtInText = builtIn[STACKED_STEP_START_EVENT[step.kind]];
  return typeof builtInText === "function" ? builtInText(step) : builtInText;
}

// -----
// The one-line summary a finished stack collapses to
// (whenDone="collapse"), e.g. "Finished · 4 steps".
// -----
export function stackedSummaryText(state: AGUILoadingStackedState): string {
  const count = stackedStepCount(state);
  const steps = `${count} ${count === 1 ? "step" : "steps"}`;
  return state.status === "done" ? `Finished · ${steps}` : `Stopped · ${steps}`;
}

// Rows of work in the stack. The error row isn't a step of work, so it isn't counted.
export function stackedStepCount(state: AGUILoadingStackedState): number {
  return state.stepOrder.filter((id) => state.steps[id]?.kind !== "error").length;
}

import {
  continuesWaitingRun,
  EventType,
  type AGUILoadingInterrupt,
  type AGUILoadingResumeEntry,
  type AGUILoadingStreamEvent,
  type AGUILoadingSubagentTag,
  type LoadingStatus,
} from "./agui-loading-machine";

// -----
// Separate reducer for the stacked loader. It reads
// the same AG-UI events as aguiLoadingReducer but keeps
// its own state, so the single-line loader's state and
// tests never change because of this one.
// -----

export type AGUILoadingStackedEvent =
  | AGUILoadingStreamEvent
  | ({ type: EventType.REASONING_START; messageId: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.REASONING_MESSAGE_START; messageId: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.REASONING_MESSAGE_CONTENT; messageId: string; delta: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.REASONING_MESSAGE_END; messageId: string } & AGUILoadingSubagentTag)
  | ({ type: EventType.REASONING_END; messageId: string } & AGUILoadingSubagentTag);

// "error" is the row RUN_ERROR adds so the failure is always visible,
// even when every other row had already finished.
export type AGUILoadingStackedStepKind =
  | "run"
  | "tool"
  | "message"
  | "reasoning"
  | "subagent"
  | "error";

export type AGUILoadingStackedStepStatus = "active" | "waiting" | "done" | "failed";

export type AGUILoadingStackedFailReason = "stopped" | "cancelled";

// -----
// One row per unit of work, not per event — a message
// streams hundreds of CONTENT deltas but stays one row
// that updates in place until TEXT_MESSAGE_END.
// -----
export type AGUILoadingStackedStep = {
  id: string;
  kind: AGUILoadingStackedStepKind;
  status: AGUILoadingStackedStepStatus;
  // Latest event for this step — drives its captions and icon.
  eventType: EventType;
  toolCallName: string | null;
  // Set on the "error" row, and on a failed subagent row.
  errorMessage: string | null;
  subagentRunId: string | null;
  subagentName: string | null;
  parentSubagentRunId: string | null;
  failReason: AGUILoadingStackedFailReason | null;
};

export type AGUILoadingStackedState = {
  status: LoadingStatus;
  runId: string | null;
  lastEventType: EventType | null;
  steps: Record<string, AGUILoadingStackedStep>;
  stepOrder: string[];
  error: { message: string; code?: string } | null;
  subagentNames: Record<string, string>;
  subagentStepIds: Record<string, string>;
  interruptIds: string[];
  interruptStepIds: Record<string, string[]>;
};

export const initialAGUILoadingStackedState: AGUILoadingStackedState = {
  status: "idle",
  runId: null,
  lastEventType: null,
  steps: {},
  stepOrder: [],
  error: null,
  subagentNames: {},
  subagentStepIds: {},
  interruptIds: [],
  interruptStepIds: {},
};

const RUN_STEP_ID = "run";
const ERROR_STEP_ID = "error";

// Prefixed so a toolCallId and a messageId can never collide.
const toolStepId = (toolCallId: string) => `tool:${toolCallId}`;
const messageStepId = (messageId: string) => `message:${messageId}`;
const reasoningStepId = (messageId: string) => `reasoning:${messageId}`;
const subagentStepId = (subagentRunId: string) => `subagent:${subagentRunId}`;

type StepOwner = Pick<AGUILoadingStackedStep, "subagentRunId" | "subagentName">;

const PARENT_OWNER: StepOwner = { subagentRunId: null, subagentName: null };

function isTerminal(state: AGUILoadingStackedState): boolean {
  return state.status === "done" || state.status === "failed" || state.status === "stopped";
}

// -----
// The subagent a tagged event belongs to, with its
// name if SUBAGENT_STARTED announced it.
// -----
function findOwner(state: AGUILoadingStackedState, event: AGUILoadingStackedEvent): StepOwner {
  const id = "subagentRunId" in event ? event.subagentRunId : undefined;
  if (id === undefined) return PARENT_OWNER;
  return { subagentRunId: id, subagentName: state.subagentNames[id] ?? null };
}

// -----
// Adds the step if new, else updates it in place.
// Real work also completes the run's own row.
// -----
function upsertStep(
  state: AGUILoadingStackedState,
  id: string,
  kind: AGUILoadingStackedStepKind,
  eventType: EventType,
  patch: Partial<AGUILoadingStackedStep> = {},
  owner: StepOwner = PARENT_OWNER,
): AGUILoadingStackedState {
  const existing = state.steps[id];
  if (existing && existing.status !== "active" && existing.status !== "waiting") {
    return { ...state, lastEventType: eventType };
  }
  const steps = { ...state.steps };
  const runStep = steps[RUN_STEP_ID];
  if (kind !== "run" && runStep?.status === "active") {
    steps[RUN_STEP_ID] = { ...runStep, status: "done" };
  }
  steps[id] = {
    ...(existing ?? {
      id,
      kind,
      status: "active",
      toolCallName: null,
      errorMessage: null,
      parentSubagentRunId: null,
      failReason: null,
      ...owner,
    }),
    eventType,
    ...patch,
  };
  return {
    ...state,
    lastEventType: eventType,
    steps,
    stepOrder: existing ? state.stepOrder : [...state.stepOrder, id],
  };
}

function updateSteps(
  state: AGUILoadingStackedState,
  update: (step: AGUILoadingStackedStep) => AGUILoadingStackedStep,
): Record<string, AGUILoadingStackedStep> {
  const steps = { ...state.steps };
  for (const id of state.stepOrder) steps[id] = update(steps[id]!);
  return steps;
}

// -----
// Ends every open row: working, or waiting on a
// suspended subagent that no interrupt followed.
// -----
function settleOpenSteps(
  state: AGUILoadingStackedState,
  status: "done" | "failed",
  failReason: AGUILoadingStackedFailReason | null = null,
): Record<string, AGUILoadingStackedStep> {
  return updateSteps(state, (step) =>
    step.status === "active" || step.status === "waiting" ? { ...step, status, failReason } : step,
  );
}

// -----
// REASONING_START and REASONING_MESSAGE_START may or
// may not share a messageId. When a reasoning event's
// id has no step yet, it joins the reasoning step
// that's already open instead of stacking a second row.
// -----
function reasoningTarget(state: AGUILoadingStackedState, messageId: string): string {
  const id = reasoningStepId(messageId);
  if (state.steps[id]) return id;
  const open = [...state.stepOrder]
    .reverse()
    .find((stepId) => {
      const step = state.steps[stepId]!;
      return step.kind === "reasoning" && step.status === "active";
    });
  return open ?? id;
}

// -----
// The subagent and every subagent nested under it,
// found through parentSubagentRunId links.
// -----
function collectSubagentFamily(state: AGUILoadingStackedState, rootId: string): Set<string> {
  const family = new Set([rootId]);
  let grew = true;
  while (grew) {
    grew = false;
    for (const id of state.stepOrder) {
      const step = state.steps[id]!;
      const child = step.kind === "subagent" ? step.subagentRunId : null;
      if (child && step.parentSubagentRunId && family.has(step.parentSubagentRunId) && !family.has(child)) {
        family.add(child);
        grew = true;
      }
    }
  }
  return family;
}

// -----
// Reuses the tool call that started it (tool mode),
// or its own row after a resume; else a new row.
// -----
function startSubagent(
  state: AGUILoadingStackedState,
  event: Extract<AGUILoadingStackedEvent, { type: EventType.SUBAGENT_STARTED }>,
): AGUILoadingStackedState {
  const parentToolStepId =
    event.parentToolCallId !== undefined ? toolStepId(event.parentToolCallId) : undefined;
  const id =
    state.subagentStepIds[event.subagentRunId] ??
    (parentToolStepId && state.steps[parentToolStepId]
      ? parentToolStepId
      : subagentStepId(event.subagentRunId));
  const next = upsertStep(
    state,
    id,
    "subagent",
    event.type,
    {
      kind: "subagent",
      status: "active",
      subagentRunId: event.subagentRunId,
      subagentName: event.name,
      parentSubagentRunId: event.parentSubagentRunId ?? null,
    },
  );
  return {
    ...next,
    subagentNames: { ...next.subagentNames, [event.subagentRunId]: event.name },
    subagentStepIds: { ...next.subagentStepIds, [event.subagentRunId]: id },
  };
}

// -----
// The run waits: rows the interrupts name wait with
// it, the rest of the open rows are done.
// -----
function waitForInterrupts(
  state: AGUILoadingStackedState,
  eventType: EventType,
  interrupts: AGUILoadingInterrupt[],
): AGUILoadingStackedState {
  const interruptStepIds: Record<string, string[]> = {};
  for (const interrupt of interrupts) {
    const ids: string[] = [];
    const subagentRow =
      interrupt.subagentRunId !== undefined ? state.subagentStepIds[interrupt.subagentRunId] : undefined;
    if (subagentRow) ids.push(subagentRow);
    const toolRow = interrupt.toolCallId !== undefined ? toolStepId(interrupt.toolCallId) : undefined;
    if (toolRow && state.steps[toolRow] && toolRow !== subagentRow) ids.push(toolRow);
    interruptStepIds[interrupt.id] = ids;
  }
  const waitingIds = new Set(Object.values(interruptStepIds).flat());
  return {
    ...state,
    status: "waiting",
    lastEventType: eventType,
    steps: updateSteps(state, (step) => {
      if (waitingIds.has(step.id)) return { ...step, status: "waiting" };
      return step.status === "active" ? { ...step, status: "done" } : step;
    }),
    interruptIds: interrupts.map((interrupt) => interrupt.id),
    interruptStepIds,
  };
}

// -----
// Picks the waiting run back up: a cancelled
// interrupt fails its rows, the rest are active.
// -----
function resumeRun(
  state: AGUILoadingStackedState,
  runId: string,
  resume: AGUILoadingResumeEntry[] | undefined,
): AGUILoadingStackedState {
  const cancelledIds = new Set(
    (resume ?? [])
      .filter((entry) => entry.status === "cancelled")
      .flatMap((entry) => state.interruptStepIds[entry.interruptId] ?? []),
  );
  return {
    ...state,
    status: "running",
    runId,
    lastEventType: EventType.RUN_STARTED,
    steps: updateSteps(state, (step) => {
      if (step.status !== "waiting") return step;
      return cancelledIds.has(step.id)
        ? { ...step, status: "failed", failReason: "cancelled" }
        : { ...step, status: "active" };
    }),
    interruptIds: [],
    interruptStepIds: {},
  };
}

// -----
// A waiting run is closed but not over: only a new
// run gets through, and it may resume this one.
// -----
export function aguiLoadingStackedReducer(
  state: AGUILoadingStackedState,
  event: AGUILoadingStackedEvent,
): AGUILoadingStackedState {
  if (isTerminal(state)) return state;
  if (state.status === "waiting" && event.type !== EventType.RUN_STARTED) return state;

  switch (event.type) {
    case EventType.RUN_STARTED:
      if (continuesWaitingRun(state, event)) {
        return resumeRun(state, event.runId, event.input?.resume);
      }
      return upsertStep(
        { ...initialAGUILoadingStackedState, status: "running", runId: event.runId },
        RUN_STEP_ID,
        "run",
        event.type,
      );

    case EventType.TOOL_CALL_START:
      return upsertStep(
        state,
        toolStepId(event.toolCallId),
        "tool",
        event.type,
        { toolCallName: event.toolCallName },
        findOwner(state, event),
      );

    // A result is what the user waited for, so it completes the row;
    // TOOL_CALL_END alone (args done, result pending) keeps it active.
    case EventType.TOOL_CALL_RESULT:
      return upsertStep(
        state,
        toolStepId(event.toolCallId),
        "tool",
        event.type,
        { status: "done" },
        findOwner(state, event),
      );

    case EventType.TOOL_CALL_END:
      return upsertStep(
        state,
        toolStepId(event.toolCallId),
        "tool",
        event.type,
        {},
        findOwner(state, event),
      );

    case EventType.TEXT_MESSAGE_START:
    case EventType.TEXT_MESSAGE_CONTENT:
      return upsertStep(
        state,
        messageStepId(event.messageId),
        "message",
        event.type,
        {},
        findOwner(state, event),
      );

    case EventType.TEXT_MESSAGE_END:
      return upsertStep(
        state,
        messageStepId(event.messageId),
        "message",
        event.type,
        { status: "done" },
        findOwner(state, event),
      );

    case EventType.REASONING_START:
    case EventType.REASONING_MESSAGE_START:
    case EventType.REASONING_MESSAGE_CONTENT:
      return upsertStep(
        state,
        reasoningTarget(state, event.messageId),
        "reasoning",
        event.type,
        {},
        findOwner(state, event),
      );

    case EventType.REASONING_MESSAGE_END:
    case EventType.REASONING_END:
      return upsertStep(
        state,
        reasoningTarget(state, event.messageId),
        "reasoning",
        event.type,
        { status: "done" },
        findOwner(state, event),
      );

    case EventType.SUBAGENT_STARTED:
      return startSubagent(state, event);

    // A suspended subagent waits for input; any other end is done.
    case EventType.SUBAGENT_FINISHED: {
      const id = state.subagentStepIds[event.subagentRunId];
      if (!id) return { ...state, lastEventType: event.type };
      const status = event.outcome?.type === "suspended" ? "waiting" : "done";
      return upsertStep(state, id, "subagent", event.type, { status });
    }

    // -----
    // Only this subagent and its own work fail. The
    // run, the parent and other subagents go on.
    // -----
    case EventType.SUBAGENT_ERROR: {
      const family = collectSubagentFamily(state, event.subagentRunId);
      const id = state.subagentStepIds[event.subagentRunId];
      const failed: AGUILoadingStackedState = {
        ...state,
        lastEventType: event.type,
        steps: updateSteps(state, (step) =>
          step.status === "active" && step.subagentRunId !== null && family.has(step.subagentRunId)
            ? { ...step, status: "failed" }
            : step,
        ),
      };
      if (!id) return failed;
      return {
        ...failed,
        steps: {
          ...failed.steps,
          [id]: { ...failed.steps[id]!, eventType: event.type, errorMessage: event.message },
        },
      };
    }

    // -----
    // Anything still open when the run ends is done;
    // an interrupt waits, a cancelled run stops.
    // -----
    case EventType.RUN_FINISHED: {
      const outcome = event.outcome;
      if (outcome?.type === "interrupt") {
        return waitForInterrupts(state, event.type, outcome.interrupts);
      }
      if (outcome?.type === "cancelled") {
        return {
          ...state,
          status: "stopped",
          lastEventType: event.type,
          steps: settleOpenSteps(state, "failed", "stopped"),
        };
      }
      return {
        ...state,
        status: "done",
        lastEventType: event.type,
        steps: settleOpenSteps(state, "done"),
      };
    }

    // -----
    // Rows still in progress fail; finished rows stay
    // done. The error also gets its own row — without
    // it, an error arriving after every row finished
    // (a tool returned, then the run failed) would leave
    // a stack that looks like a clean success.
    // -----
    case EventType.RUN_ERROR:
      return {
        ...state,
        status: "failed",
        lastEventType: event.type,
        steps: {
          ...settleOpenSteps(state, "failed"),
          [ERROR_STEP_ID]: {
            id: ERROR_STEP_ID,
            kind: "error",
            status: "failed",
            eventType: event.type,
            toolCallName: null,
            errorMessage: event.message,
            parentSubagentRunId: null,
            failReason: null,
            ...PARENT_OWNER,
          },
        },
        stepOrder: [...state.stepOrder, ERROR_STEP_ID],
        error: { message: event.message, code: event.code },
      };

    default:
      return state;
  }
}

